<!--vbase-->
<template>
    <q-table
      class="text-uppercase sticky-header transparent-header table_height resizable"
      :class="custom_class"
      :rows="tableRows"
      :columns="tableColumns"
      :sort-method="customSort"
      row-key="id"
      :table-header-style="{ backgroundColor: '#d4d4d4' }"
      :rows-per-page-options="[0]"
      id="po-table"
      selection="single"
      :no-data-label="$t('no_data_found')"
      :loading="loading"
      ref="el"
    >
      <template v-slot:header="props">
        <q-tr :props="props" class="" :class="''">
          <q-th
            v-for="(col, index) in props.cols"
            :key="col.name"
            :props="props"
            :data-index="index"
            draggable="true"
            dropzone="true"
            direction="horizontal"
            @dragstart="onDragStart($event, tableColumns, index)"
            @drop.prevent="handleDrop($event, index)"
            @dragover.prevent="onDragOver($event, index)"
            @dragenter.prevent="onDragEnter"
            @dragleave.prevent="onDragLeave"
            :style="{ cursor: getIsDragging ? 'pointer' : 'move' }"
            :class="'po_table_header cursor-move'"
          >
            <span v-if="col.label == 'position'" class="float-right">{{
              col.label
            }}</span>
            <span
              v-else
              :class="
                col.is_bold || col.name === po_quantity_column
                  ? 'text-weight-bolder font-size-14'
                  : ''
              "
            >
              {{ col.label }}
            </span>
          </q-th>
        </q-tr>
      </template>

      <template v-slot:body="props">
        <q-tr
          :props="props"
          :id="props.key"
          class="po_iterateable_item compact-table-tr-37"
          tabindex="0"
          :class="
            (props.row['is_draggable'] ? 'draggable' : 'un-draggable') +
            ' ' +
            (props.rowIndex % 2 == 0 ? '' : '') +
            ' ' +
            (po_line_id_for_match == props.key ? 'selected_for_match' : '')
          "
          :data-id="props.key"
        >
          <template v-for="col in props.cols" :key="col.name" :props="props">
            <q-td
              v-if="col.name === 'buttons'"
              :data-id="props.key"
              class="actions"
              :class="props.row['is_draggable'] ? 'draggable' : 'un-draggable'"
            >
              <q-img
                v-if="isChargesModule"
                @click="toggleExpand(props.row)"
                :class="
                  !getPoLineCharges(
                    props.row.line_number,
                    props.row.sub_line_number,
                  )
                    ? 'item-disabled'
                    : 'cursor-pointer'
                "
                src="/images/charges/charges.svg"
                height="21px"
                width="19px"
                class="icon-grey-svg"
                id="icon_charge"
              >
                <q-tooltip>
                  {{ $t('charges') }}
                </q-tooltip>
              </q-img>
            </q-td>

            <q-td
              v-else-if="col.name === 'status'"
              :data-id="props.key"
              :class="props.row['is_draggable'] ? 'draggable' : 'un-draggable'"
            >
              <q-badge
                transparent
                align="middle"
                :color="statusColor(props.row[col.name])"
              >
                {{ props.row[col.name] }}
              </q-badge>
            </q-td>

            <q-td
              v-else
              :data-id="props.key"
              :class="props.row['is_draggable'] ? 'draggable' : 'un-draggable'"
            >
              <span
                :class="checkIfColumnIsAmount(col.name) ? 'float-right' : ''"
              >
                {{ colValue(props.row, col.name) }}
              </span>
            </q-td>
          </template>
        </q-tr>

        <q-tr v-show="props.expand" :props="props">
          <q-td
            class="sub-table-main-td"
            colspan="100%"
            v-if="
              !po_connected_line_items[props.key] ||
              po_connected_line_items[props.key].hasOwnProperty('table_line_id')
            "
          >
            <div class="text-left sub-table">No multi-match Information</div>
          </q-td>
          <q-td colspan="100%" class="sub-table-main-td" v-else>
            <q-markup-table v-show="props.expand" class="sub-table">
              <thead>
                <tr class="compact-table-tr">
                  <th class="text-left data-td">
                    {{ $t('position') }}
                  </th>
                  <th class="text-left data-td">{{ $t('quantity') }}</th>
                  <th class="text-left data-td">{{ $t('unit_price') }}</th>
                  <th colspan="20"></th>
                </tr>
              </thead>
              <tbody>
                <template
                  v-for="(table_line, index) in po_connected_line_items[
                    props.key
                  ].table_lines"
                  :key="table_line.table_line_id"
                >
                  <tr :class="index % 2 == 0 ? '' : ''">
                    <td class="text-left data-td">
                      {{
                        lineDataObj[table_line.table_line_id].columns.POSITION
                          .formatted_value
                      }}
                    </td>
                    <td class="text-left data-td">
                      {{
                        lineDataObj[table_line.table_line_id].columns.QUANTITY
                          .formatted_value
                      }}
                    </td>
                    <td class="text-left data-td">
                      {{
                        lineDataObj[table_line.table_line_id].columns.UNIT_PRICE
                          .formatted_value
                      }}
                    </td>
                    <td colspan="20"></td>
                  </tr>
                </template>
              </tbody>
            </q-markup-table>
          </q-td>
        </q-tr>
        <q-tr v-show="props.row.expand" :props="props" class="charges-row compact-table-tr">
          <q-td></q-td>
          <template v-for="(col, colIndex) in props.cols.slice(1)" :key="'header-' + col.name">
            <q-td v-if="colIndex === 0" class="charges-header-cell">{{ $t('charge_id') }}</q-td>
            <q-td v-else-if="colIndex === 1" class="charges-header-cell text-right">{{ $t('amount') }}</q-td>
            <q-td v-else-if="colIndex === 2" class="charges-header-cell">{{ $t('charge_type') }}</q-td>
            <q-td v-else-if="colIndex === 3" class="charges-header-cell">{{ $t('purchase_order_number') }}</q-td>
            <q-td v-else></q-td>
          </template>
        </q-tr>
        <template v-for="(table_line, chargeIndex) in props.row.po_charge_item" :key="'charge-' + table_line.line_number + '-' + table_line.charge_id + '-' + chargeIndex">
          <q-tr v-show="props.row.expand && table_line.charge_id" :props="props" class="charges-row compact-table-tr">
            <q-td></q-td>
            <template v-for="(col, colIndex) in props.cols.slice(1)" :key="'data-' + col.name + '-' + chargeIndex">
              <q-td v-if="colIndex === 0" :class="{ 'charges-data-cell': true, 'charges-alt-cell': +chargeIndex % 2 !== 0 }">
                <q-icon v-if="costingElementDictionary && costingElementDictionary[table_line.charge_id]" :name="'img:images/charges/' + costingElementDictionary[table_line.charge_id].icon" size="xs" class="icon-grey-svg q-mr-sm"/>
                <span>{{ table_line.charge_id }}</span>
              </q-td>
              <q-td v-else-if="colIndex === 1" :class="{ 'charges-data-cell': true, 'charges-alt-cell': +chargeIndex % 2 !== 0, 'text-right': true }">{{ table_line.formattedAmount }}</q-td>
              <q-td v-else-if="colIndex === 2" :class="{ 'charges-data-cell': true, 'charges-alt-cell': +chargeIndex % 2 !== 0 }">{{ table_line.charge_type }}</q-td>
              <q-td v-else-if="colIndex === 3" :class="{ 'charges-data-cell': true, 'charges-alt-cell': +chargeIndex % 2 !== 0 }">{{ table_line.purchase_order_number }}</q-td>
              <q-td v-else></q-td>
            </template>
          </q-tr>
        </template>
      </template>
    </q-table>
</template>

<script lang="ts">
// @ts-nocheck
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { type dynamicObj, $ } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import helperMixin from 'src/mixins/helperMixin';
import dragDropColumn from 'src/mixins/dragDropColumn';
import lineItemsBaseMixin from 'src/mixins/lineItemsBaseMixin';
import MaterialIconSet from 'quasar/icon-set/material-icons';
import { useTableHeightResize } from 'src/utils/tableHeightResizeUtil';
import { po_table_columns, charges_table_extraction } from 'src/constants';
import {
  getStatusColor,
  AMOUNT_COLUMNS,
} from 'src/pages/PurchaseOrders/constants.js';
import {
  usePoMatchStore,
  useSettingStore,
  useDocumentStore,
  useAmountFormatStore,
  useDocAttributesStore,
  useMasterDataLookupStore,
} from 'src/store/main';
import { isUndefinedOrNull } from 'src/utils/general';
import { notify } from 'src/components/notifications/notify';

MaterialIconSet.table.arrowUp = 'arrow_drop_down';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin, dragDropColumn, lineItemsBaseMixin],
  props: {
    visible_columns: {
      type: Object,
      default: () => ({}),
    },
    po_lines: {
      type: Array,
      default: () => [],
    },
    po_number: {
      type: String,
      default: '',
    },
    loading: {
      type: Boolean,
      default: false,
    },
  },
  components: {},
  data() {
    return {
      AMOUNT_COLUMNS,
      po_connected_line_items: {} as { [k: string]: any },
      loading_data: false,
      isChargesModule: ref(false),
      additional_columns: [
        'delivery_number',
        'delivery_line_number',
      ] as string[],
      po_table_columns,
    };
  },
  mounted: function () {
    document.addEventListener('init_po_lines', this.loadPurchaseOrderData);
    this.loadPurchaseOrderData();
    this.initailizeDragColumnsById('po-table');
    document.addEventListener('po-table-column-drop', this.onDropColumns);
  },
  unmounted: function () {
    document.removeEventListener('init_po_lines', this.loadPurchaseOrderData);
    document.removeEventListener('po-table-column-drop', this.onDropColumns);
  },
  updated() {
    this.applyStoredHeight('po-table');
  },
  watch: {
    po_lines: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.loadPurchaseOrderData();
      },
    },
  },
  methods: {
    onDropColumns() {
      const columnList: any = {};
      this.tableColumns.forEach((element: any, index: number) => {
        columnList[element.name] = this.visible_columns[element.name];
        if (columnList[element.name]) {
          columnList[element.name]['order'] = index;
        }
      });

      this.saveOrderColumns(columnList);
    },
    async saveOrderColumns(columns: any) {
      try {
        let fv_po_key = this.po_table_columns + '_' + this.doctype;
        await this.updateSetting(fv_po_key, JSON.stringify(columns));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    checkIfColumnIsAmount(columnName: string) {
      let isAmount = false;
      if (this.AMOUNT_COLUMNS.includes(columnName.toLowerCase())) {
        isAmount = true;
      }
      return isAmount;
    },
    colValue(row: any, col_name: any) {
      let value = row[col_name];
      if (row.hasOwnProperty(col_name + '_formatted_value')) {
        value = row[col_name + '_formatted_value'];
      }

      return value as string;
    },

    isNotEditable() {
      return !this.record.editable || this.is_view_readonly;
    },

    loadPurchaseOrderData() {
      try {
        if (this.loading_data) {
          return;
        }
        this.loading_data = true;
        this.setConnectedPoRecords();
        this.checkForAdditionalColumns();
        this.prepareTableColumn();
        this.prepareTableRows();

        if (this.user_settings[charges_table_extraction]) {
          this.isChargesModule = true;
        }

        this.loading_data = false;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    prepareTableColumn() {
      this.tableColumns = [];
      // empty Column for buttons
      let columnItem = {
        name: 'buttons',
        field: 'buttons',
        align: 'left',
        label: '',
        order: 0,
      };
      this.tableColumns.push(columnItem);

      let additional_columns_added = false;
      Array.from(Object.keys(this.visible_columns)).forEach(
        (columnKey: string) => {
          let column = this.visible_columns[columnKey];
          let item = {
            name: column.name,
            field: column.name,
            align: 'left',
            label: this.$t(column.translation_key),
            sortable: true,
            is_bold: this.isColumnBold(column.name),
            order: column.order,
          };

          this.tableColumns.push(Object.assign({}, item));
          if (
            column.name == 'purchase_order_number' &&
            this.add_additional_columns
          ) {
            additional_columns_added = true;
            this.addAdditionalColumns();
          }
        },
      );

      if (!additional_columns_added && this.add_additional_columns) {
        this.addAdditionalColumns();
      }

      // sort
      this.tableColumns.sort((a: any, b: any) => {
        return a.order - b.order;
      });
    },

    addAdditionalColumns() {
      let order = 25;
      for (let [col_index, name] of Object.entries(this.additional_columns)) {
        let item = {
          name: name,
          field: name,
          align: 'left',
          label: this.$t(name),
          sortable: true,
          is_bold: this.isColumnBold(name),
          order: order++,
        };
        this.tableColumns.push(Object.assign({}, item));
      }
    },
    isColumnBold(columnName: string) {
      return false;
    },

    async prepareTableRows() {
      this.custom_class = '';
      this.tableRows = [];
      if (!this.po_lines || this.po_lines.length == 0) {
        notify.error(this.$t('no_connected_po_lines_found'));
        return;
      }
      await this.fetchAttributes(this.doctype);
      this.po_lines.forEach((row: any, index: any) => {
        let newRow: dynamicObj = {};
        newRow['connection_data'] = {};
        newRow['connected'] = false;
        newRow['id'] = row.id;
        newRow['show_menu'] = false;
        newRow['line_number'] = row.line_number;
        newRow['sub_line_number'] = row.sub_line_number;

        let checkStatus = this.doc_attributes['PO_DISABLED_STATUSES'];
        if (isUndefinedOrNull(row.status)) {
          row.status = '';
        }
        if (checkStatus && checkStatus.includes(row.status.toLowerCase())) {
          newRow['is_draggable'] = false;
        } else {
          newRow['is_draggable'] = true;
        }

        if (this.po_connected_line_items.hasOwnProperty(row.id)) {
          newRow['connected'] = true;
          newRow['connection_data'] = this.po_connected_line_items[row.id];
        }

        for (let [col_index, col] of Object.entries(this.tableColumns)) {
          const column = col as dynamicObj;
          newRow[column.name] = this.colValue(row, column.name);

          // Also store unformated value
          let columnValueKey = column.name + '_value';
          if (row.hasOwnProperty(columnValueKey)) {
            newRow[columnValueKey] = row[columnValueKey];
          }
        }
        this.tableRows.push(newRow);
      });

      // Show error if tableRows is empty after processing
      if (!this.tableRows || this.tableRows.length === 0) {
        notify.error(this.$t('no_connected_po_lines_found'));
      }

      this.calculateTableHeight();
    },

    calculateTableHeight() {
      if (this.tableRows.length < 3) {
        this.custom_class = 'height-20vh';
      }
    },

    checkForAdditionalColumns() {
      if (this.po_lines.length == 0) {
        return;
      }

      // if any of the columns has value then add all of them in the columns list
      this.po_lines.forEach((row: any, index: any) => {
        for (let [col_index, name] of Object.entries(this.additional_columns)) {
          if (
            row.hasOwnProperty(name) &&
            row[name] != null &&
            row[name] != ''
          ) {
            this.add_additional_columns = true;
            break;
          }
        }
      });
    },

    setConnectedPoRecords() {
      this.po_connected_line_items = {} as dynamicObj;
      let po_matching = this.getConnectedLineItems();

      if (!po_matching || po_matching.length == 0) {
        return;
      }
      for (let [index, record] of po_matching.entries()) {
        if (record.hasOwnProperty('po_line_id')) {
          this.po_connected_line_items[record.po_line_id] = record;
        } else if (record.hasOwnProperty('sub_lines')) {
          for (let [index, po_sub_lines] of record.sub_lines.entries()) {
            this.po_connected_line_items[po_sub_lines.po_line_id] = record;
          }
        }
      }
    },
    statusColor(status: string) {
      return getStatusColor(status.toLowerCase()) || 'primary';
    },
    customSort(rows: any, sortBy: string, descending: boolean): any {
      const data = [...rows] as any;
      let columnName = sortBy + '_value';

      if (!data[0].hasOwnProperty(columnName)) {
        columnName = sortBy;
      }

      if (sortBy) {
        data.sort((a: any, b: any) => {
          const x = descending ? b : a;
          const y = descending ? a : b;

          if (this.checkIfColumnIsAmount(sortBy)) {
            // numeric sort
            return parseFloat(x[columnName]) - parseFloat(y[columnName]);
          } else {
            // string sort
            return x[sortBy] > y[sortBy] ? 1 : x[sortBy] < y[sortBy] ? -1 : 0;
          }
        });
      }

      return data;
    },
    async toggleExpand(row: any) {
      const charges = this.getPoLineCharges(
        row.line_number,
        row.sub_line_number,
      );
      if (charges) {
        row.po_charge_item = charges;

        if (row.po_charge_item) {
          for (const charge of row.po_charge_item) {
            charge.formattedAmount = await this.formatAmount(charge.amount);
          }
        }
      }
      row.expand = !row.expand;
    },
    getPoLineCharges(po_line_number: string, po_sub_line_number: string) {
      const charge = this.charges[this.po_number] as dynamicObj;
      if (charge && charge[po_line_number]) {
        return charge[po_line_number].filter(
          (charge: dynamicObj) => charge.sub_line_number === po_sub_line_number,
        ) as dynamicObj;
      }
      return false;
    },
    async formatAmount(amount: string) {
      const values = [];
      if (amount) {
        values.push({
          key: amount,
          value: amount,
        });
      } else {
        values.push({
          key: 0,
          value: 0,
        });
      }

      const result = await this.formatMultiValues(
        values,
        'en_US',
        this.user_settings.AMOUNTS_LOCALE,
      );

      if (result) {
        return this.searchValueByKey(amount, result);
      }
    },
  },
  setup() {
    let data: any = [];
    const el = ref() as any;

    const doc_attribute_store = useDocAttributesStore();
    const { model: doc_attributes } = storeToRefs(doc_attribute_store);
    const { fetchAttributes } = doc_attribute_store;

    const amount_format_store = useAmountFormatStore();
    const { searchValueByKey, formatMultiValues } = amount_format_store;

    const master_data_lookup = useMasterDataLookupStore();
    const { costingElementDictionary } = storeToRefs(master_data_lookup);

    const po_match_store = usePoMatchStore();
    const {
      charges,
      PODataObj,
      lineDataObj,
      is_view_readonly,
      po_line_for_match,
      po_quantity_column,
      po_line_id_for_match,
      line_connected_items,
    } = storeToRefs(po_match_store);

    const doc_store = useDocumentStore();
    const { record, doctype } = storeToRefs(doc_store);

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    // Table height resize functionality
    const { applyStoredHeight, initResizeObserver } = useTableHeightResize(el, {
      settingKey: 'PO_SUB_TABLE_SETTING',
      minHeight: 200
    });

    // Initialize the resize observer
    initResizeObserver();

    return {
      el,
      charges,
      doctype,
      user_settings,
      updateSetting,
      fetchAttributes,
      searchValueByKey,
      formatMultiValues,
      po_quantity_column,
      line_connected_items,
      po_line_id_for_match,
      po_line_for_match,
      PODataObj,
      record,
      is_view_readonly,
      lineDataObj,
      doc_attributes,
      tableRows: ref(data),
      tableColumns: ref(data),
      add_additional_columns: ref(false),
      custom_class: ref(''),
      costingElementDictionary
    };
  },
});
</script>

